package com.tura.ventas.controlador;
import java.time.LocalDate; import java.util.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import com.tura.ventas.service.*;
@Controller public class VentaController { private final VentaService vs; private final ClienteService cs; private final ProductoService ps; public VentaController(VentaService v,ClienteService c,ProductoService p){vs=v;cs=c;ps=p;}
 @GetMapping("/ventas") String listar(Model m){m.addAttribute("clientes",cs.listar(null));m.addAttribute("productos",ps.listar(null));m.addAttribute("listaVentas",vs.listarCabeceras());m.addAttribute("fechaHoy",LocalDate.now());return "ventas";}
 @PostMapping("/ventas/registrar") String registrar(@RequestParam String numero,@RequestParam Integer codigoCliente,@RequestParam(required=false) String ruc,@RequestParam(defaultValue="1") Integer moneda,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fecha,@RequestParam("productoId") List<Integer> productos,@RequestParam("cantidadDetalle") List<Integer> cantidades,RedirectAttributes ra){try{if(productos.size()!=cantidades.size())throw new IllegalArgumentException("El detalle de la venta está incompleto.");List<VentaService.Linea> lineas=new ArrayList<>();for(int i=0;i<productos.size();i++)lineas.add(new VentaService.Linea(productos.get(i),cantidades.get(i)));vs.registrarCabecera(numero,codigoCliente,ruc,moneda,fecha,lineas);ra.addFlashAttribute("mensaje","Venta registrada correctamente.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/ventas";}
 @PostMapping("/ventas/eliminar/{id}") String eliminar(@PathVariable Integer id,RedirectAttributes ra){try{vs.eliminarCabecera(id);ra.addFlashAttribute("mensaje","Venta eliminada y stock devuelto.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/ventas";}
}
